-- +goose Up
-- Catalog service: products, SKUs, prices, media.
-- SQLite version: 3.38+ recommended for JSON support.
-- UUIDs are generated by the application.
-- Timestamps use SQLite's UTC  (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')) format.
CREATE TABLE
    category (
        id TEXT PRIMARY KEY NOT NULL,
        parent_id TEXT REFERENCES category (id),
        name TEXT NOT NULL,
        slug TEXT NOT NULL UNIQUE,
        created_at TEXT NOT NULL DEFAULT  (strftime('%Y-%m-%dT%H:%M:%SZ', 'now'))
    );

CREATE INDEX idx_category_parent ON category (parent_id);

CREATE TABLE
    product (
        id TEXT PRIMARY KEY NOT NULL,
        name TEXT NOT NULL,
        slug TEXT NOT NULL UNIQUE,
        description TEXT,
        category_id TEXT REFERENCES category (id),
        brand TEXT,
        status TEXT NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT', 'ACTIVE', 'ARCHIVED')),
        created_at TEXT NOT NULL DEFAULT  (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
        updated_at TEXT NOT NULL DEFAULT  (strftime('%Y-%m-%dT%H:%M:%SZ', 'now'))
    );

CREATE INDEX idx_product_category ON product (category_id);

CREATE INDEX idx_product_status ON product (status);

CREATE TABLE
    sku (
        id TEXT PRIMARY KEY NOT NULL,
        product_id TEXT NOT NULL REFERENCES product (id),
        sku_code TEXT NOT NULL UNIQUE,
        attributes TEXT NOT NULL DEFAULT '{}' CHECK (json_valid (attributes)),
        price_minor INTEGER NOT NULL CHECK (price_minor >= 0),
        currency TEXT NOT NULL DEFAULT 'INR' CHECK (length (currency) = 3),
        active INTEGER NOT NULL DEFAULT 0 CHECK (active IN (0, 1)),
        available_quantity INTEGER NOT NULL DEFAULT 0 CHECK (available_quantity >= 0),
        quantity_updated_at TEXT NOT NULL DEFAULT  (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
        created_at TEXT NOT NULL DEFAULT  (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
        updated_at TEXT NOT NULL DEFAULT  (strftime('%Y-%m-%dT%H:%M:%SZ', 'now'))
    );

CREATE INDEX idx_sku_product ON sku (product_id);

